## 14. 扇出 / 扇入（Fan-out / Fan-in）模式

- **扇出（Fan-out）**：多个 goroutine 从**同一个**通道读取，并行处理，提升吞吐。
- **扇入（Fan-in）**：把**多个**通道的结果合并到**一个**通道。

```go
package main

import (
    "fmt"
    "sync"
    "time"
)

// 扇出：3 个 worker 并发消费同一个 in 通道
func fanOut(in <-chan int, workers int) {
    var wg sync.WaitGroup
    for w := 0; w < workers; w++ {
        wg.Add(1)
        go func(id int) {
            defer wg.Done()
            for v := range in { // 多个 goroutine 抢同一个 in，Go 保证每条消息只被一个消费
                fmt.Printf("worker%d 处理 %d\n", id, v)
                time.Sleep(20 * time.Millisecond)
            }
        }(w)
    }
    wg.Wait()
}

// 扇入：把多个输入通道合并到一个输出
func fanIn(chans ...<-chan int) <-chan int {
    out := make(chan int)
    var wg sync.WaitGroup
    for _, c := range chans {
        wg.Add(1)
        go func(c <-chan int) {
            defer wg.Done()
            for v := range c {
                out <- v
            }
        }(c)
    }
    go func() {
        wg.Wait()
        close(out) // 所有输入都结束后才关闭 out
    }()
    return out
}

func main() {
    in := make(chan int, 10)
    for i := 0; i < 6; i++ {
        in <- i
    }
    close(in)
    fanOut(in, 3)

    // 扇入示例
    a := make(chan int, 2)
    b := make(chan int, 2)
    a <- 1
    a <- 2
    b <- 3
    b <- 4
    close(a)
    close(b)
    for v := range fanIn(a, b) {
        fmt.Println("扇入收到:", v)
    }
}
```

