## 17. 与 GORM 集成（数据库）

GORM 是 Go 最流行的 ORM。示例展示 Gin + GORM + SQLite 的最小 CRUD。

```bash
go get gorm.io/gorm gorm.io/driver/sqlite
```

```go
package main

import (
	"net/http"

	"github.com/gin-gonic/gin"
	"gorm.io/driver/sqlite"
	"gorm.io/gorm"
)

// 模型
type User struct {
	gorm.Model
	Name  string `json:"name" binding:"required"`
	Email string `json:"email" binding:"required,email"`
}

var db *gorm.DB

func initDB() {
	var err error
	db, err = gorm.Open(sqlite.Open("test.db"), &gorm.Config{})
	if err != nil {
		panic("数据库连接失败")
	}
	// 自动建表
	_ = db.AutoMigrate(&User{})
}

func main() {
	initDB()
	r := gin.Default()

	// 创建
	r.POST("/users", func(c *gin.Context) {
		var u User
		if err := c.ShouldBindJSON(&u); err != nil {
			c.JSON(400, gin.H{"msg": err.Error()})
			return
		}
		db.Create(&u)
		c.JSON(201, u)
	})

	// 列表
	r.GET("/users", func(c *gin.Context) {
		var users []User
		db.Find(&users)
		c.JSON(200, users)
	})

	// 详情
	r.GET("/users/:id", func(c *gin.Context) {
		var u User
		if err := db.First(&u, c.Param("id")).Error; err != nil {
			c.JSON(404, gin.H{"msg": "用户不存在"})
			return
		}
		c.JSON(200, u)
	})

	// 更新
	r.PUT("/users/:id", func(c *gin.Context) {
		var u User
		if err := db.First(&u, c.Param("id")).Error; err != nil {
			c.JSON(404, gin.H{"msg": "用户不存在"})
			return
		}
		var input User
		if err := c.ShouldBindJSON(&input); err != nil {
			c.JSON(400, gin.H{"msg": err.Error()})
			return
		}
		db.Model(&u).Updates(input)
		c.JSON(200, u)
	})

	// 删除
	r.DELETE("/users/:id", func(c *gin.Context) {
		db.Delete(&User{}, c.Param("id"))
		c.JSON(200, gin.H{"msg": "deleted"})
	})

	r.Run(":8080")
}
```

