```tsx
// 1) CSS Modules（局部作用域，推荐）
import styles from './button.module.css';

export default function Button() {
  return <button className={styles.primary}>提交</button>;
}
```

```css
/* button.module.css */
.primary { background: #0070f3; color: #fff; }
