```tsx
// expo-secure-store —— 密钥安全存储（iOS Keychain / Android Keystore）
import * as SecureStore from 'expo-secure-store';

await SecureStore.setItemAsync('token', 'abc');
const token = await SecureStore.getItemAsync('token');
