        <TextInput value={field.value} onChangeText={field.onChange} placeholder="邮箱" />
      )} />
      {errors.email && <Text>{errors.email.message}</Text>}
      <Button title="提交" onPress={handleSubmit(onSubmit)} />
    </>
  );
}
